class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        INF_NEG = -10**15                     # smaller than any possible profit

        # dp[i][j][k] – profit reaching (i,j) using exactly k neutralisations
        dp = [[[INF_NEG] * 3 for _ in range(n)] for _ in range(m)]

        # ----- initialise start cell -----
        start_val = coins[0][0]
        for used in range(3):
            # without neutralising this cell
            dp[0][0][used] = start_val
            # possibly neutralise it (only useful if negative)
            if start_val < 0 and used >= 1:
                dp[0][0][used] = max(dp[0][0][used], 0)

        # ----- fill the DP table -----
        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                val = coins[i][j]
                for used in range(3):
                    best = INF_NEG
                    if i > 0:
                        best = max(best, dp[i - 1][j][used])
                    if j > 0:
                        best = max(best, dp[i][j - 1][used])
                    if best == INF_NEG:
                        continue

                    # 1) do NOT neutralise this cell
                    dp[i][j][used] = max(dp[i][j][used], best + val)

                    # 2) neutralise (only if cell is negative and we have a free neutralisation)
                    if val < 0 and used + 1 <= 2:
                        dp[i][j][used + 1] = max(dp[i][j][used + 1], best)   # profit unchanged

        # ----- answer -----
        last = dp[m - 1][n - 1]
        return max(last[0], last[1], last[2])

class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # try every possible start position
        for i in range(n - k + 1):
            ch = s[i]
            # 1. check that the whole window is the same character
            ok = True
            for j in range(1, k):
                if s[i + j] != ch:
                    ok = False
                    break
            if not ok:
                continue

            # 2. left neighbour must be different (if it exists)
            if i > 0 and s[i - 1] == ch:
                continue

            # 3. right neighbour must be different (if it exists)
            if i + k < n and s[i + k] == ch:
                continue

            # all conditions satisfied
            return True

        return False

