class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # threshold is >= 1, therefore it never restricts the construction.
        # Build reversed graph: edge (a -> b, w) becomes (b -> a, w)
        rev = [[] for _ in range(n)]
        for a, b, w in edges:
            rev[b].append((a, w))

        INF = 10 ** 18
        dist = [INF] * n
        dist[0] = 0
        pq = [(0, 0)]                     # (current bottleneck, node)

        while pq:
            cur, u = heapq.heappop(pq)
            if cur != dist[u]:
                continue
            for v, w in rev[u]:
                nd = cur if cur > w else w   # max(cur, w) without function call
                if nd < dist[v]:
                    dist[v] = nd
                    heapq.heappush(pq, (nd, v))

        # check reachability
        max_needed = 0
        for d in dist:
            if d == INF:
                return -1
            if d > max_needed:
                max_needed = d
        return max_needed

