class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # 1. first occurrence of each element value
        first_index = {}
        for idx, val in enumerate(elements):
            if val not in first_index:          # keep only the smallest index
                first_index[val] = idx

        INF = len(elements) + 5                 # larger than any possible index
        answer = []

        # 2. process each group independently
        for g in groups:
            best = INF
            limit = int(math.isqrt(g))
            for d in range(1, limit + 1):
                if g % d != 0:
                    continue
                # divisor d
                if d in first_index:
                    if first_index[d] < best:
                        best = first_index[d]
                # paired divisor g//d (may be equal to d)
                other = g // d
                if other != d and other in first_index:
                    if first_index[other] < best:
                        best = first_index[other]
            answer.append(best if best != INF else -1)

        return answer

