class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        """
        Returns the smallest y-coordinate Y such that the total area of the given
        squares above the horizontal line y = Y equals the total area below it.
        """
        # pre‑compute total area and search bounds
        total_area = 0.0
        min_y = float('inf')
        max_y = -float('inf')
        for x, y, l in squares:
            total_area += l * l
            if y < min_y:
                min_y = y
            top = y + l
            if top > max_y:
                max_y = top

        target = total_area / 2.0

        # helper: area below a given Y
        def area_below(Y: float) -> float:
            area = 0.0
            for x, y, l in squares:
                if Y <= y:
                    continue                     # completely above the line
                elif Y >= y + l:
                    area += l * l                # completely below the line
                else:
                    area += l * (Y - y)          # partially cut
            return area

        low, high = min_y, max_y
        # binary search for the leftmost Y with area >= target
        for _ in range(80):               # enough for 1e-5 precision
            mid = (low + high) * 0.5
            if area_below(mid) < target:
                low = mid
            else:
                high = mid

        return high

