class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        # collect the useful candidates: top 'limit' values of each row
        candidates = []
        for row, lim in zip(grid, limits):
            if lim == 0:
                continue
            # number of elements we can actually take from this row
            take_cnt = min(lim, len(row))
            if take_cnt == len(row):
                # whole row fits, no need for nlargest
                candidates.extend(row)
            else:
                # take the largest 'take_cnt' elements
                candidates.extend(heapq.nlargest(take_cnt, row))

        if k == 0 or not candidates:
            return 0

        if k >= len(candidates):
            return sum(candidates)

        # sum of the k largest numbers among all candidates
        top_k = heapq.nlargest(k, candidates)
        return sum(top_k)

