class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[par][p] = set of alternating sums reachable
        # par = 0 -> next sign is '+', par = 1 -> next sign is '-'
        dp = [ [set() for _ in range(limit + 1)] for _ in range(2) ]

        for x in nums:
            # copy current tables (skipping the element)
            newdp0 = [s.copy() for s in dp[0]]
            newdp1 = [s.copy() for s in dp[1]]

            # 1) start a new subsequence consisting only of x
            if x <= limit:
                p = x
                newdp1[p].add(x)          # sum = +x, next parity = 1

            # 2) extend already existing subsequences
            for parity in (0, 1):
                src = dp[parity]          # states before using x
                dst = newdp1 if parity == 0 else newdp0   # parity flips
                for p in range(limit + 1):
                    if not src[p]:
                        continue
                    newp = p * x
                    if newp > limit:
                        continue
                    for s in src[p]:
                        ns = s + x if parity == 0 else s - x
                        dst[newp].add(ns)

            # replace old tables with the updated ones
            dp[0] = newdp0
            dp[1] = newdp1

        # find the biggest product whose set contains k
        answer = -1
        for p in range(limit + 1):
            if k in dp[0][p] or k in dp[1][p]:
                if p > answer:
                    answer = p
        return answer

