class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # circular distance between two letters
        def circ_dist(a: int, b: int) -> int:
            d = abs(a - b)
            return d if d <= 13 else 26 - d   # 13 = 26//2

        # pre‑compute pair costs for the whole string
        cost_pair = [[0] * n for _ in range(n)]
        for i in range(n):
            ci = ord(s[i]) - 97
            for j in range(i + 1, n):
                cj = ord(s[j]) - 97
                cost_pair[i][j] = circ_dist(ci, cj)

        # dp[i][j][c] – see explanation
        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        # length 1 intervals
        for i in range(n):
            for c in range(k + 1):
                dp[i][i][c] = 1

        # intervals of increasing length
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                pair_cost = cost_pair[i][j]          # 0 … 13
                for c in range(k + 1):
                    # skip one end
                    best = dp[i + 1][j][c]
                    if dp[i][j - 1][c] > best:
                        best = dp[i][j - 1][c]

                    # use both ends as a pair
                    if c >= pair_cost:
                        cand = dp[i + 1][j - 1][c - pair_cost] + 2
                        if cand > best:
                            best = cand

                    dp[i][j][c] = best

                # make values monotone w.r.t. the budget
                for c in range(1, k + 1):
                    if dp[i][j][c - 1] > dp[i][j][c]:
                        dp[i][j][c] = dp[i][j][c - 1]

        return dp[0][n - 1][k]

