class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # ---------- segment tree ----------
        size = 1
        while size < n:
            size <<= 1
        # tree indexed from 1, total 2*size
        tree = [0] * (2 * size)

        # build leaves
        for i in range(n):
            tree[size + i] = baskets[i]
        # build internal nodes (max)
        for i in range(size - 1, 0, -1):
            tree[i] = max(tree[i << 1], tree[i << 1 | 1])

        # helper: set position pos to value val (0) and update upwards
        def update(pos: int, val: int = 0) -> None:
            idx = size + pos
            tree[idx] = val
            idx >>= 1
            while idx:
                tree[idx] = max(tree[idx << 1], tree[idx << 1 | 1])
                idx >>= 1

        # helper: find leftmost index with value >= need, return -1 if none
        def query(node: int, l: int, r: int, need: int) -> int:
            if tree[node] < need:
                return -1
            if l == r:
                return l
            mid = (l + r) // 2
            left = node << 1
            if tree[left] >= need:
                return query(left, l, mid, need)
            else:
                return query(left | 1, mid + 1, r, need)

        # ---------- main loop ----------
        unplaced = 0
        for fruit in fruits:
            idx = query(1, 0, size - 1, fruit)   # note: tree covers [0, size-1]
            if idx == -1 or idx >= n:            # idx may lie in padded part
                unplaced += 1
            else:
                update(idx, 0)                    # mark basket as used

        return unplaced

