class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)

        # turn each row into a set of distinct integers
        sets = [set(row) for row in properties]

        # ----- Union Find -----
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]   # path compression
                x = parent[x]
            return x

        def union(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # ----- build edges -----
        for i in range(n):
            si = sets[i]
            for j in range(i + 1, n):
                if len(si & sets[j]) >= k:   # intersect size
                    union(i, j)

        # ----- count components -----
        roots = {find(i) for i in range(n)}
        return len(roots)

