def count_upto(x: int) -> int:
    """return number of Snake numbers <= x"""
    if x < 10:
        return 0
    digits = list(map(int, str(x)))
    n = len(digits)

    @lru_cache(maxsize=None)
    def dp(pos: int, tight: int, started: int, first: int, has_other: int) -> int:
        """number of ways to fill positions [pos, n) under given state"""
        if pos == n:
            # valid Snake number iff we have started and placed at least one other digit
            return 1 if started and has_other else 0

        limit = digits[pos] if tight else 9
        total = 0
        for d in range(limit + 1):
            new_tight = tight and (d == limit)

            if not started:
                if d == 0:
                    # still leading zeros
                    total += dp(pos + 1, new_tight, 0, 0, 0)
                else:
                    # first non‑zero digit becomes the most significant digit
                    total += dp(pos + 1, new_tight, 1, d, 0)
            else:
                # already have a most significant digit = first
                if d >= first:
                    continue          # would violate the Snake condition
                # place a following digit (now we have at least one)
                total += dp(pos + 1, new_tight, 1, first, 1)
        return total

    return dp(0, 1, 0, 0, 0)


